mutations.find:
salary = Fraction(0)
    for word in tokens:
        if word == '.':
            break
        salary += values.get(word, 0)

mutations.replace:
salary = Fraction(0)
    seen = set()
    for word in tokens:
        if word == '.':
            break
        if word not in seen:
            salary += values.get(word, 0)
            seen.add(word)
